//! The two generated files: `docs/DIFFERENCES.md` for people and `docs/differences.json` for the
//! parity harness.

use serde::Serialize;

use super::{
    validate::{Entry, Ledger, Pattern},
    vocab::{CATEGORIES, INPUTS, KINDS, REFUSED_CLASSES, REFUSED_KINDS, RuleB, Status},
};

/// The `schema` member of `docs/differences.json`.
const SCHEMA: &str = "pbs-differences/1";

/// The first line of `docs/DIFFERENCES.md`.
const HEADER: &str = "<!-- Generated by pbs-differences from the crates/*/differences.toml \
                      fragments; do not edit. Change a fragment, then run: cargo run -p \
                      pbs-differences --locked --offline -- --write -->";

/// What the ledger is, before the summary.
const INTRO: &[&str] = &[
    "# Differences from the Go server",
    "",
    "The Rust server builds on Rust crates where the Go server builds on Go libraries: serde_json \
     for encoding/json and jsoniter, reqwest for the net/http client, axum and tower-http for the \
     server, and so on through the crate stack. This ledger lists every observable difference \
     that brings, and every place where the port keeps Go's behaviour on purpose. Each crate \
     records its entries in `crates/<crate>/differences.toml`; `pbs-differences` validates them \
     and writes this file and `docs/differences.json`, which the parity harness reads, and CI \
     checks that both are current.",
    "",
    "An entry says what Go does, what Rust does, who could notice (publisher, bidder, operator, \
     analytics or none), where it shows, how the parity harness recognises it, and its pin: the \
     test that shows both behaviours next to a golden written by the Go code. Its status is one \
     of:",
    "",
    "- **Decision pending**: the default applies until the user decides; the decision is in \
     `docs/DECISIONS.md`.",
    "- **Ledgered**: the crate's behaviour is accepted (Rule A).",
    "- **Go behaviour kept** (restored): glue under one of Rule B's four cases, Prebid's own logic \
     ported onto the crate, or a decided decision keeps what Go does, and a restore pin compares \
     it with a Go golden. A mismatch on such an entry is never ledgered.",
    "- **Extension beyond Go** (extension): an opt-in feature Go does not have, off by default. \
     Off, the server behaves as Go's does, which the entry's pin shows; its Rust text says what \
     happens with it on. Parity runs keep it off, so a mismatch on such an entry is unexpected.",
    "",
    "Rule B's cases: (a) input real production traffic sends that the crate would reject or \
     misread; (b) state one server writes and the other reads while Go and Rust run side by \
     side; (c) the operator interface: config keys, defaults, `PBS_` variables, CLI flags, metric \
     names, labels and types; (d) Prebid-authored texts and bytes.",
];

/// How the harness matches an entry, before the list of input predicates.
const MATCHING: &[&str] = &[
    "## How the parity harness matches an entry",
    "",
    "A mismatch is ledgered under an entry when one of the entry's harness patterns has the \
     mismatch's kind, its class (the pattern's `lexical_class`, for the lexical and wire kinds) \
     and a path that matches the mismatch's path with every array index written `[*]`; a pattern \
     that names an input predicate matches only in a case that has it. Every other mismatch is \
     unexpected. A restored entry has no pattern, so a mismatch where Go's behaviour is kept is \
     unexpected too, and neither has an extension entry, which parity runs keep off. No two \
     patterns match one mismatch, except patterns that name different input predicates; a case \
     with both features is tagged with the entry first in id order.",
    "",
    "Paths are the harness's JSON paths: `$` is the compared value, `.name` a member whose name \
     is an identifier, `['name']` any other member, with `\\` and `'` escaped (meta members such \
     as `['@status']` and `['@headers']` are always bracketed), and `[*]` any array index. A \
     pattern may also use `.*` for any one member and `.**` for any run of members and indices, \
     the empty run included. A pattern of kind `value`, `type`, `missing_in_rust`, \
     `extra_in_rust` or `status` names a concrete path, with no `.*` or `.**`, and a `status` \
     pattern names an input predicate, so a status mismatch on any other case stays unexpected.",
];

/// `text` in a code span.
fn code(text: &str) -> String {
    format!("`{text}`")
}

/// `items` joined as a sentence: `a`, `a and b`, `a, b and c`.
fn and_list(items: &[String]) -> String {
    match items {
        [] => String::new(),
        [one] => one.clone(),
        [init @ .., last] => format!("{} and {last}", init.join(", ")),
    }
}

/// The entries of `status`, in id order.
fn with_status(entries: &[Entry], status: Status) -> impl Iterator<Item = &Entry> {
    entries.iter().filter(move |entry| entry.status == status)
}

/// The summary table: one row per category with entries, then the totals.
fn summary(ledger: &Ledger, out: &mut Vec<String>) {
    out.push("## Summary".to_owned());
    out.push(String::new());
    out.push(
        "| Category | Decision pending | Ledgered | Go behaviour kept | Extensions |".to_owned(),
    );
    out.push("|---|---:|---:|---:|---:|".to_owned());
    let count = |entries: &[&Entry], status: Status| {
        entries
            .iter()
            .filter(|entry| entry.status == status)
            .count()
    };
    let all: Vec<&Entry> = ledger.entries.iter().collect();
    for category in CATEGORIES {
        let entries: Vec<&Entry> = all
            .iter()
            .copied()
            .filter(|entry| entry.category.id == category.id)
            .collect();
        if !entries.is_empty() {
            out.push(format!(
                "| {} | {} | {} | {} | {} |",
                category.title,
                count(&entries, Status::DecisionPending),
                count(&entries, Status::Ledgered),
                count(&entries, Status::Restored),
                count(&entries, Status::Extension)
            ));
        }
    }
    out.push(format!(
        "| All | {} | {} | {} | {} |",
        count(&all, Status::DecisionPending),
        count(&all, Status::Ledgered),
        count(&all, Status::Restored),
        count(&all, Status::Extension)
    ));
    out.push(String::new());
}

/// The decision-pending entries with their defaults, which the user decides.
fn decisions(ledger: &Ledger, out: &mut Vec<String>) {
    out.push("## Decisions pending".to_owned());
    out.push(String::new());
    let mut any = false;
    for entry in with_status(&ledger.entries, Status::DecisionPending) {
        any = true;
        out.push(format!(
            "- {} ({}): {}. Default until decided: {}",
            code(&entry.id),
            entry.decision.as_deref().unwrap_or_default(),
            entry.title,
            entry.default.as_deref().unwrap_or_default()
        ));
    }
    if !any {
        out.push("None.".to_owned());
    }
    out.push(String::new());
}

/// The restored entries whose restore pin has not landed.
fn pending(ledger: &Ledger, out: &mut Vec<String>) {
    out.push("## Restore pins still to land".to_owned());
    out.push(String::new());
    let mut any = false;
    for entry in ledger
        .entries
        .iter()
        .filter(|entry| entry.restore_pending())
    {
        any = true;
        out.push(format!(
            "- {}: brought by {}.",
            code(&entry.id),
            and_list(&entry.restore_by)
        ));
    }
    if !any {
        out.push("None.".to_owned());
    }
    out.push(String::new());
}

/// How the harness matches entries, with the vocabularies the patterns use.
fn matching(out: &mut Vec<String>) {
    out.extend(MATCHING.iter().map(|line| (*line).to_owned()));
    out.push(String::new());
    for kind in KINDS.iter().filter(|kind| !kind.classes.is_empty()) {
        let classes: Vec<String> = kind.classes.iter().map(|class| code(class)).collect();
        out.push(format!(
            "The {} classes are {}.",
            kind.name,
            and_list(&classes)
        ));
        out.push(String::new());
    }
    let refused_classes: Vec<String> = REFUSED_CLASSES.iter().map(|(name, _)| code(name)).collect();
    let refused_kinds: Vec<String> = REFUSED_KINDS.iter().map(|(name, _)| code(name)).collect();
    out.push(format!(
        "No entry names the classes {} or the kinds {}: they name no difference a crate makes.",
        and_list(&refused_classes),
        and_list(&refused_kinds)
    ));
    out.push(String::new());
    out.push("| Input predicate | A case has it when |".to_owned());
    out.push("|---|---|".to_owned());
    for input in INPUTS {
        out.push(format!("| {} | {} |", code(input.name), input.description));
    }
    out.push(String::new());
}

/// One harness pattern in words, with its parts in code spans.
fn pattern_words(pattern: &Pattern) -> String {
    let class = pattern
        .class
        .map_or_default(|class| format!(" {}", code(class)));
    let input = pattern
        .input
        .map_or_default(|input| format!(" when the case has {}", code(input.name)));
    format!(
        "{}{class} at {}{input}",
        pattern.kind.name,
        code(&pattern.path.to_string())
    )
}

/// One entry.
fn entry(entry: &Entry, out: &mut Vec<String>) {
    out.push(format!("#### {}: {}", code(&entry.id), entry.title));
    out.push(String::new());
    out.push(format!("- **Go:** {}", entry.go));
    if entry.status == Status::Extension {
        out.push(format!("- **Rust, with the extension on:** {}", entry.rust));
    } else {
        out.push(format!("- **Rust:** {}", entry.rust));
    }
    out.push(format!("- **Who notices:** {}", entry.who.join(", ")));
    out.push(format!("- **Visible in:** {}", entry.visible_in));
    let harness = if entry.harness.is_empty() {
        if matches!(entry.status, Status::Restored | Status::Extension) {
            "none: a mismatch here is unexpected".to_owned()
        } else {
            "none".to_owned()
        }
    } else {
        entry
            .harness
            .iter()
            .map(pattern_words)
            .collect::<Vec<_>>()
            .join("; ")
    };
    out.push(format!("- **Harness:** {harness}"));
    if entry.status == Status::Extension {
        out.push(format!("- **Pin (off is Go):** {}", code(&entry.pin)));
    } else {
        out.push(format!("- **Pin:** {}", code(&entry.pin)));
    }
    if let Some(case) = entry.rule_b {
        out.push(format!("- **Rule B:** {}", case.describe()));
    }
    if let Some(decision) = &entry.decision {
        out.push(format!("- **Decision:** {decision}"));
    }
    if let Some(default) = &entry.default {
        out.push(format!("- **Default until decided:** {default}"));
    }
    if let Some(restore) = &entry.restore {
        let label = if entry.status == Status::Restored {
            "How Go's behaviour is kept"
        } else {
            "Restore option"
        };
        out.push(format!("- **{label}:** {restore}"));
    }
    if entry.status == Status::Restored {
        let pins = if entry.restorations.is_empty() {
            format!("pending, brought by {}", and_list(&entry.restore_by))
        } else {
            entry
                .restorations
                .iter()
                .map(|restoration| {
                    let note = restoration
                        .note
                        .as_ref()
                        .map_or_default(|note| format!(" ({note})"));
                    format!("{}{note}", code(&restoration.pin))
                })
                .collect::<Vec<_>>()
                .join("; ")
        };
        out.push(format!("- **Restore pin:** {pins}"));
    }
    if let Some(note) = &entry.note {
        out.push(format!("- **Note:** {note}"));
    }
    out.push(format!("- **Recorded in:** {}", code(&entry.fragment)));
    out.push(String::new());
}

/// `docs/DIFFERENCES.md`.
pub(super) fn markdown(ledger: &Ledger) -> String {
    let mut out = vec![HEADER.to_owned(), String::new()];
    out.extend(INTRO.iter().map(|line| (*line).to_owned()));
    out.push(String::new());
    summary(ledger, &mut out);
    decisions(ledger, &mut out);
    pending(ledger, &mut out);
    matching(&mut out);
    for category in CATEGORIES {
        let in_category: Vec<&Entry> = ledger
            .entries
            .iter()
            .filter(|entry| entry.category.id == category.id)
            .collect();
        if in_category.is_empty() {
            continue;
        }
        out.push(format!("## {}", category.title));
        out.push(String::new());
        for status in Status::ALL {
            let mut listed = in_category
                .iter()
                .filter(|entry| entry.status == status)
                .peekable();
            if listed.peek().is_none() {
                continue;
            }
            out.push(format!("### {}", status.heading()));
            out.push(String::new());
            for listed_entry in listed {
                entry(listed_entry, &mut out);
            }
        }
    }
    let mut text = out.join("\n");
    text.truncate(text.trim_end().len());
    text.push('\n');
    text
}

/// `docs/differences.json`.
#[derive(Debug, Serialize)]
struct Document<'l> {
    /// The format of this file.
    schema: &'static str,
    /// The fragments read.
    fragments: &'l [String],
    /// The input predicates patterns may name.
    inputs: Vec<InputJson>,
    /// Every entry, in id order.
    differences: Vec<EntryJson<'l>>,
}

/// An input predicate.
#[derive(Debug, Serialize)]
struct InputJson {
    /// The predicate's name.
    name: &'static str,
    /// When a case has it.
    description: &'static str,
}

/// An entry.
#[derive(Debug, Serialize)]
struct EntryJson<'l> {
    /// The dotted id.
    id: &'l str,
    /// The category.
    category: &'static str,
    /// The status.
    status: &'static str,
    /// One line on the difference.
    title: &'l str,
    /// What Go does.
    go: &'l str,
    /// What Rust does.
    rust: &'l str,
    /// Who could notice.
    who: &'l [&'static str],
    /// Where it shows.
    visible_in: &'l str,
    /// How the harness recognises it.
    harness: Vec<PatternJson>,
    /// The pin.
    pin: &'l str,
    /// The restore option, or what keeps Go's behaviour.
    restore: Option<&'l str>,
    /// What applies until the user decides.
    default: Option<&'l str>,
    /// The decision it depends on.
    decision: Option<&'l str>,
    /// The Rule B case.
    rule_b: Option<&'static str>,
    /// The units whose merge brings the restore pin.
    restore_by: &'l [String],
    /// The restore pins.
    restorations: Vec<RestorationJson<'l>>,
    /// Whether a restored entry still waits for its restore pin.
    restore_pending: bool,
    /// Anything else a reader needs.
    note: Option<&'l str>,
    /// The fragment that records it.
    fragment: &'l str,
}

/// A harness pattern.
#[derive(Debug, Serialize)]
struct PatternJson {
    /// The mismatch kind.
    kind: &'static str,
    /// The lexical class, which a lexical or wire mismatch record carries as `class`.
    lexical_class: Option<&'static str>,
    /// The path pattern.
    path: String,
    /// The input predicate.
    input: Option<&'static str>,
}

/// A restore pin.
#[derive(Debug, Serialize)]
struct RestorationJson<'l> {
    /// The test.
    pin: &'l str,
    /// Anything else a reader needs.
    note: Option<&'l str>,
    /// The fragment that brings it.
    fragment: &'l str,
}

/// `docs/differences.json`, pretty-printed with a final newline.
///
/// # Errors
///
/// When `serde_json` fails to write the document.
pub(super) fn json(ledger: &Ledger) -> Result<String, serde_json::Error> {
    let document = Document {
        schema: SCHEMA,
        fragments: &ledger.fragments,
        inputs: INPUTS
            .iter()
            .map(|input| InputJson {
                name: input.name,
                description: input.description,
            })
            .collect(),
        differences: ledger
            .entries
            .iter()
            .map(|entry| EntryJson {
                id: &entry.id,
                category: entry.category.id,
                status: entry.status.name(),
                title: &entry.title,
                go: &entry.go,
                rust: &entry.rust,
                who: &entry.who,
                visible_in: &entry.visible_in,
                harness: entry
                    .harness
                    .iter()
                    .map(|pattern| PatternJson {
                        kind: pattern.kind.name,
                        lexical_class: pattern.class,
                        path: pattern.path.to_string(),
                        input: pattern.input.map(|input| input.name),
                    })
                    .collect(),
                pin: &entry.pin,
                restore: entry.restore.as_deref(),
                default: entry.default.as_deref(),
                decision: entry.decision.as_deref(),
                rule_b: entry.rule_b.map(RuleB::name),
                restore_by: &entry.restore_by,
                restorations: entry
                    .restorations
                    .iter()
                    .map(|restoration| RestorationJson {
                        pin: &restoration.pin,
                        note: restoration.note.as_deref(),
                        fragment: &restoration.fragment,
                    })
                    .collect(),
                restore_pending: entry.restore_pending(),
                note: entry.note.as_deref(),
                fragment: &entry.fragment,
            })
            .collect(),
    };
    let mut text = serde_json::to_string_pretty(&document)?;
    text.push('\n');
    Ok(text)
}
